//! Signature specification type shared between the build script and
//! the runtime database.
//!
//! `SignatureSpec` is the compile-time representation (from the TOML
//! files). `Signature` is the runtime representation (in the
//! `SignatureDb`).

use crate::SignatureId;
use serde::{Deserialize, Serialize};

/// A single magic byte: `Some(byte)` = must match this byte, `None` =
/// wildcard (match any byte).
pub type MagicByte = Option<u8>;

/// Compile-time signature specification.
///
/// Generated by `build.rs` from the TOML files under
/// `assets/public-signatures/`. Embedded in the binary as a `const`
/// array.
#[derive(Debug, Clone)]
pub struct SignatureSpec {
    pub extension: &'static str,
    pub mime: Option<&'static str>,
    pub header_offset: u32,
    pub header_magic: &'static [MagicByte],
    pub tail_offset: u32,
    pub tail_magic: Option<&'static [MagicByte]>,
    pub min_size: u64,
    pub max_size: u64,
    pub weight: u16,
    pub source: &'static str,
}

/// Runtime signature (owned, in the `SignatureDb`).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Signature {
    pub id: SignatureId,
    pub extension: String,
    pub mime: Option<String>,
    pub header_offset: u32,
    /// Header magic: `Some(byte)` = must match, `None` = wildcard.
    pub header_magic: Vec<MagicByte>,
    pub tail_offset_from_end: u32,
    pub tail_magic: Vec<MagicByte>,
    pub min_size: u64,
    pub max_size: u64,
    pub weight: u16,
    pub source: String,
}

impl From<&SignatureSpec> for Signature {
    fn from(spec: &SignatureSpec) -> Self {
        Self {
            id: SignatureId(0), // reassigned by SignatureDb::push
            extension: spec.extension.to_string(),
            mime: spec.mime.map(|s| s.to_string()),
            header_offset: spec.header_offset,
            header_magic: spec.header_magic.to_vec(),
            tail_offset_from_end: spec.tail_offset,
            tail_magic: spec.tail_magic.map(|s| s.to_vec()).unwrap_or_default(),
            min_size: spec.min_size,
            max_size: spec.max_size,
            weight: spec.weight,
            source: spec.source.to_string(),
        }
    }
}
